<?php
$page_title='Tải giảng theo ngày';
require_once __DIR__.'/includes/functions.php';
require_once __DIR__.'/includes/timetable_store.php';
require_once __DIR__.'/includes/teacher_daily_load.php';
$user=cds_user();if(!$user){header('Location: /login.php?next='.urlencode($_SERVER['REQUEST_URI']??''));exit;}
if(!cds_can_daily_teacher_load()){http_response_code(403);exit('Bạn chưa được phân quyền xem tải giảng giáo viên theo ngày.');}
$param=static fn($key,$default='')=>is_string($_GET[$key]??null)?trim($_GET[$key]):$default;
$date=$param('date',date('Y-m-d'));$parsed=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$parsed||$parsed->format('Y-m-d')!==$date)$date=date('Y-m-d');
$scope=$param('scope','day');if(!in_array($scope,['day','morning','afternoon'],true))$scope='day';
$countFilter=$param('lessons','all');if($countFilter!=='all'&&!preg_match('/^(?:0|[1-9][0-9]?)$/D',$countFilter))$countFilter='all';
$weekId=$param('week_id');$weeks=tkb_weeks();$week=$weekId!==''?tkb_week_by_id($weekId):null;
$contains=static function($w)use($date){$start=(string)($w['start_date']??'');return preg_match('/^\d{4}-\d{2}-\d{2}$/D',$start)&&$date>=$start&&$date<=date('Y-m-d',strtotime($start.' +6 days'));};
if(!$week||!$contains($week)){$week=null;foreach($weeks as$w)if($contains($w)){$week=$w;break;}}
if(!$week){$active=tkb_active_week();if($active&&$contains($active))$week=$active;}
$slots=$week?tkb_resolved_slots($week):[];$day=(int)date('N',strtotime($date))+1;
// Resolve approved replacements once for this date instead of rescanning the store per lesson.
$replacements=[];if($week)foreach(tkb_week_substitutions($week,true)as$sub)if(($sub['date']??'')===$date&&trim((string)($sub['substitute_teacher']??''))!=='')if(!isset($replacements[(string)($sub['slot_key']??'')]))$replacements[(string)($sub['slot_key']??'')]=$sub['substitute_teacher'];
foreach($slots as&$slot)if((int)($slot['day']??0)===$day&&isset($replacements[tkb_slot_key($slot)]))$slot['_actual_teacher']=$replacements[tkb_slot_key($slot)];unset($slot);
$teachers=array_values(array_filter((array)load_json(TEACHERS_FILE,[]),'is_string'));
$filters=['scope'=>$scope,'lessons'=>$countFilter,'teacher'=>$param('teacher'),'subject'=>$param('subject'),'class'=>$param('class')];
$report=td_daily_matrix($teachers,$slots,$day,$filters);$hasSchedule=$week&&count($slots)>0;$rows=$hasSchedule?$report['rows']:[];
$sessions=$scope==='day'?['morning'=>'BUỔI SÁNG','afternoon'=>'BUỔI CHIỀU']:[$scope=>$scope==='morning'?'BUỔI SÁNG':'BUỔI CHIỀU'];$scopeLabel=$scope==='day'?'Cả ngày':($scope==='morning'?'Buổi sáng':'Buổi chiều');
$url=static fn($changes=[])=>BASE_URL.'tkb_taigiang.php?'.http_build_query(array_merge(['week_id'=>$weekId,'date'=>$date],$filters,$changes));
$columnCount=3;foreach($sessions as$key=>$label)$columnCount+=$report['periods'][$key];
require_once __DIR__.'/includes/header.php';
?>
