<div class="col-6 col-lg-2"><label class="form-label" for="load-count">Số tiết thực tế</label><select id="load-count" class="form-select" name="lessons"><option value="all">Tất cả</option><?php $maxCount=max(8,...array_keys($report['distribution']?:[0=>0]));for($n=0;$n<=$maxCount;$n++):?><option value="<?=$n?>" <?=$countFilter===(string)$n?'selected':''?>><?=$n===0?'Không có tiết':$n.' tiết'?></option><?php endfor;?></select></div>
