</div></form>
<?php if(!$hasSchedule):?><div class="alert alert-warning mt-3" role="status">Chưa có dữ liệu thời khóa biểu phù hợp ngày này. Chưa thể kết luận giáo viên có lịch hay trống tiết.</div><?php else:?>
<section class="load-summary" aria-label="Tổng hợp tải giảng"><div><strong><?=$report['stats']['teachers']?></strong>Giáo viên trong bộ lọc</div><div><strong><?=$report['stats']['busy']?></strong>Có lịch <?=$scopeLabel?></div><div><strong><?=$report['stats']['free']?></strong>Trống <?=$scopeLabel?></div><div><strong><?=$report['stats']['matched']?></strong>Tiết phù hợp môn / lớp</div></section>
<p class="load-legend"><b>Trống</b>: không có tiết theo TKB. <b>Lịch khác</b>: đang bận ở môn/lớp ngoài bộ lọc. Tổng tiết tính theo lịch thực tế, gồm dạy thay đã duyệt. Khi lọc môn/lớp, danh sách gồm giáo viên có phân công phù hợp trong tuần.</p>
<?php if($report['stats']['conflicts']):?><div class="alert alert-danger"><?=$report['stats']['conflicts']?> ô bị trùng lịch; kiểm tra các ô đánh dấu bên dưới.</div><?php endif;?>
<?php if($report['invalid']):?><div class="alert alert-warning">Có <?=$report['invalid']?> tiết chưa có số tiết hợp lệ trong dữ liệu nguồn.</div><?php endif;?>
