<div class="load-matrix-wrap" tabindex="0" aria-label="Bảng giáo viên theo từng tiết, cuộn ngang để xem đủ buổi"><table class="load-matrix"><caption class="visually-hidden">Lịch giáo viên theo từng tiết ngày <?=e($date)?></caption><thead><tr><th rowspan="2">STT</th><th rowspan="2" class="load-name">Giáo viên</th><?php foreach($sessions as$key=>$label):?><th colspan="<?=$report['periods'][$key]?>" class="load-session-<?=$key?>"><?=$label?></th><?php endforeach;?><th rowspan="2">Tổng tiết<br><?=$scopeLabel?></th></tr><tr><?php foreach($sessions as$key=>$label):for($period=1;$period<=$report['periods'][$key];$period++):?><th class="load-period load-session-<?=$key?>">Tiết <?=$period?></th><?php endfor;endforeach;?></tr></thead><tbody>
<?php if(!$rows):?><tr><td colspan="<?=$columnCount?>" class="load-empty">Không có giáo viên phù hợp bộ lọc.</td></tr><?php endif;?>
